    </mxCell>&#xa;&#xa;        <!-- Platform Adapter (callback) -->&#xa;        <mxCell id=\"h-pa\" value=\"Platform Adapter&#10;(callback)\" style=\"shape=umlLifeline;perimeter=lifelinePerimeter;whiteSpace=wrap;html=1;container=0;collapsible=0;recursiveResize=0;outlineConnect=0;fillColor=#F2F2F2;strokeColor=#999999;fontSize=12;fontStyle=1;size=60;\" vertex=\"1\" parent=\"1\">&#xa;          <mxGeometry x=\"1390\" y=\"60\" width=\"120\" height=\"1100\" as=\"geometry\"/>&#xa;        </mxCell>&#xa;&#xa;        <!-- DLQ -->&#xa;        <mxCell id=\"h-dlq\" value=\"DLQ\" style=\"shape=umlLifeline;perimeter=lifelinePerimeter;whiteSpace=wrap;html=1;container=0;collapsible=0;recursiveResize=0;outlineConnect=0;fillColor=#FFE6E6;strokeColor=#CC0000;fontSize=12;fontStyle=1;size=60;\" vertex=\"1\" parent=\"1\">&#xa;          <mxGeometry x=\"1570\" y=\"60\" width=\"100\" height=\"1100\" as=\"geometry\"/>&#xa;        </mxCell>&#xa;&#xa;        <!-- ===== MESSAGE 1: DocuSign → Adapter: webhook ===== -->&#xa;        <mxCell id=\"m1\" value=\"webhook(envelopeId, status, metadata)\" style=\"html=1;verticalAlign=bottom;endArrow=block;endFill=1;rounded=0;fontSize=11;\" edge=\"1\" parent=\"1\">&#xa;          <mxGeometry relative=\"1\" as=\"geometry\">&#xa;            <mxPoint x=\"120\" y=\"180\" as=\"sourcePoint\"/>&#xa;            <mxPoint x=\"310\" y=\"180\" as=\"targetPoint\"/>&#xa;          </mxGeometry>&#xa;        </mxCell>&#xa;&#xa;        <!-- Note: Adapter processing -->&#xa;        <mxCell id=\"note-adapter\" value=\"Validate signature webhook&#10;Persist raw payload (landing store)&#10;Publish event to Service Bus\" style=\"shape=note;whiteSpace=wrap;html=1;size=14;fillColor=#FFF9E6;strokeColor=#D6B656;fontSize=10;align=left;spacingLeft=5;\" vertex=\"1\" parent=\"1\">&#xa;          <mxGeometry x=\"320\" y=\"190\" width=\"220\" height=\"60\" as=\"geometry\"/>&#xa;        </mxCell>&#xa;&#xa;        <!-- ===== MESSAGE 2: Adapter → Service Bus: publish event ===== -->&#xa;        <mxCell id=\"m2\" value=\"publish DocuSignEnvelopeUpdated&#10;{applicationId, envelopeId,&#10;signatureStatus, timestamp, eventId}\" style=\"html=1;verticalAlign=bottom;endArrow=block;endFill=1;rounded=0;fontSize=10;\" edge=\"1\" parent=\"1\">&#xa;          <mxGeometry relative=\"1\" as=\"geometry\">&#xa;            <mxPoint x=\"310\" y=\"270\" as=\"sourcePoint\"/>&#xa;            <mxPoint x=\"500\" y=\"270\" as=\"targetPoint\"/>&#xa;          </mxGeometry>&#xa;        </mxCell>&#xa;&#xa;        <!-- ===== MESSAGE 3: Service Bus → App Processing: deliver ===== -->&#xa;        <mxCell id=\"m3\" value=\"deliver DocuSignEnvelopeUpdated\" style=\"html=1;verticalAlign=bottom;endArrow=block;endFill=1;rounded=0;fontSize=11;\" edge=\"1\" parent=\"1\">&#xa;          <mxGeometry relative=\"1\" as=\"geometry\">&#xa;            <mxPoint x=\"500\" y=\"330\" as=\"sourcePoint\"/>&#xa;            <mxPoint x=\"690\" y=\"330\" as=\"targetPoint\"/>&#xa;          </mxGeometry>&#xa;        </mxCell>&#xa;&#xa;        <!-- ===== MESSAGE 4: App Processing self-call: idempotency ===== -->&#xa;        <mxCell id=\"m4\" value=\"idempotency check(eventId/envelopeId)&#10;validate &amp; map to applicationId\" style=\"html=1;verticalAlign=bottom;endArrow=block;endFill=1;rounded=0;fontSize=10;curved=1;\" edge=\"1\" parent=\"1\">&#xa;          <mxGeometry relative=\"1\" as=\"geometry\">&#xa;            <mxPoint x=\"695\" y=\"370\" as=\"sourcePoint\"/>&#xa;            <mxPoint x=\"695\" y=\"410\" as=\"targetPoint\"/>&#xa;            <Array as=\"points\">&#xa;              <mxPoint x=\"760\" y=\"370\"/>&#xa;              <mxPoint x=\"760\" y=\"410\"/>&#xa;            </Array>&#xa;          </mxGeometry>&#xa;        </mxCell>&#xa;&#xa;        <!-- ===== MESSAGE 5: App Processing → DB: update ===== -->&#xa;        <mxCell id=\"m5\" value=\"update application record&#10;(signatureStatus, lastUpdated)\" style=\"html=1;verticalAlign=bottom;endArrow=block;endFill=1;rounded=0;fontSize=11;\" edge=\"1\" parent=\"1\">&#xa;          <mxGeometry relative=\"1\" as=\"geometry\">&#xa;            <mxPoint x=\"690\" y=\"440\" as=\"sourcePoint\"/>&#xa;            <mxPoint x=\"880\" y=\"440\" as=\"targetPoint\"/>&#xa;          </mxGeometry>&#xa;        </mxCell>&#xa;&#xa;        <!-- ===== MESSAGE 6: App Processing → Domain Events: publish ===== -->&#xa;        <mxCell id=\"m6\" value=\"publish ApplicationStatusUpdated&#10;{applicationId, applicationStatus,&#10;signatureStatus, transferMoney,&#10;eventId, timestamp}\" style=\"html=1;verticalAlign=bottom;endArrow=block;endFill=1;rounded=0;fontSize=10;\" edge=\"1\" parent=\"1\">&#xa;          <mxGeometry relative=\"1\" as=\"geometry\">&#xa;            <mxPoint x=\"690\" y=\"500\" as=\"sourcePoint\"/>&#xa;            <mxPoint x=\"1070\" y=\"500\" as=\"targetPoint\"/>&#xa;          </mxGeometry>&#xa;        </mxCell>&#xa;&#xa;        <!-- ===== MESSAGE 7: Domain Events → Notification: deliver ===== -->&#xa;        <mxCell id=\"m7\" value=\"deliver ApplicationStatusUpdated\" style=\"html=1;verticalAlign=bottom;endArrow=block;endFill=1;rounded=0;fontSize=11;\" edge=\"1\" parent=\"1\">&#xa;          <mxGeometry relative=\"1\" as=\"geometry\">&#xa;            <mxPoint x=\"1070\" y=\"570\" as=\"sourcePoint\"/>&#xa;            <mxPoint x=\"1260\" y=\"570\" as=\"targetPoint\"/>&#xa;          </mxGeometry>&#xa;        </mxCell>&#xa;&#xa;        <!-- ===== MESSAGE 8: Notification self-call: prepare callback ===== -->&#xa;        <mxCell id=\"m8\" value=\"prepare callback payload&#10;apply idempotency(eventId)\" style=\"html=1;verticalAlign=bottom;endArrow=block;endFill=1;rounded=0;fontSize=10;curved=1;\" edge=\"1\" parent=\"1\">&#xa;          <mxGeometry relative=\"1\" as=\"geometry\">&#xa;            <mxPoint x=\"1265\" y=\"610\" as=\"sourcePoint\"/>&#xa;            <mxPoint x=\"1265\" y=\"650\" as=\"targetPoint\"/>&#xa;            <Array as=\"points\">&#xa;              <mxPoint x=\"1330\" y=\"610\"/>&#xa;              <mxPoint x=\"1330\" y=\"650\"/>&#xa;            </Array>&#xa;          </mxGeometry>&#xa;        </mxCell>&#xa;&#xa;        <!-- ===== MESSAGE 9: Notification → Platform: POST ===== -->&#xa;        <mxCell id=\"m9\" value=\"POST /application-status (payload)\" style=\"html=1;verticalAlign=bottom;endArrow=block;endFill=1;rounded=0;fontSize=11;\" edge=\"1\" parent=\"1\">&#xa;          <mxGeometry relative=\"1\" as=\"geometry\">&#xa;            <mxPoint x=\"1260\" y=\"680\" as=\"sourcePoint\"/>&#xa;            <mxPoint x=\"1450\" y=\"680\" as=\"targetPoint\"/>&#xa;          </mxGeometry>&#xa;        </mxCell>&#xa;&#xa;        <!-- ===== ALT FRAME: Response Handling ===== -->&#xa;        <mxCell id=\"alt-frame\" value=\"alt\" style=\"shape=umlFrame;whiteSpace=wrap;html=1;width=30;height=20;fillColor=none;strokeColor=#333333;fontSize=11;fontStyle=1;\" vertex=\"1\" parent=\"1\">&#xa;          <mxGeometry x=\"1170\" y=\"700\" width=\"480\" height=\"380\" as=\"geometry\"/>&#xa;        </mxCell>&#xa;&#xa;        <!-- ALT: 2xx Success -->&#xa;        <mxCell id=\"alt-label-2xx\" value=\"[Platform returns 2xx]\" style=\"text;html=1;align=left;verticalAlign=middle;fontSize=11;fontStyle=2;fontColor=#009900;fillColor=none;strokeColor=none;\" vertex=\"1\" parent=\"1\">&#xa;          <mxGeometry x=\"1180\" y=\"720\" width=\"200\" height=\"20\" as=\"geometry\"/>&#xa;        </mxCell>&#xa;&#xa;        <mxCell id=\"m10\" value=\"200 OK\" style=\"html=1;verticalAlign=bottom;endArrow=open;endFill=0;dashed=1;rounded=0;fontSize=11;strokeColor=#009900;\" edge=\"1\" parent=\"1\">&#xa;          <mxGeometry relative=\"1\" as=\"geometry\">&#xa;            <mxPoint x=\"1450\" y=\"755\" as=\"sourcePoint\"/>&#xa;            <mxPoint x=\"1260\" y=\"755\" as=\"targetPoint\"/>&#xa;          </mxGeometry>&#xa;        </mxCell>&#xa;&#xa;        <mxCell id=\"m11\" value=\"publish NotificationDelivered&#10;{eventId, deliveredAt}\" style=\"html=1;verticalAlign=bottom;endArrow=block;endFill=1;rounded=0;fontSize=10;strokeColo