         <mxGeometry x=\"1170\" y=\"930\" width=\"480\" height=\"1\" as=\"geometry\"/>&#xa;        </mxCell>&#xa;&#xa;        <!-- ALT: 5xx / timeout -->&#xa;        <mxCell id=\"alt-label-5xx\" value=\"[Platform returns 5xx / timeout]\" style=\"text;html=1;align=left;verticalAlign=middle;fontSize=11;fontStyle=2;fontColor=#CC6600;fillColor=none;strokeColor=none;\" vertex=\"1\" parent=\"1\">&#xa;          <mxGeometry x=\"1180\" y=\"940\" width=\"250\" height=\"20\" as=\"geometry\"/>&#xa;        </mxCell>&#xa;&#xa;        <mxCell id=\"m14\" value=\"5xx / timeout\" style=\"html=1;verticalAlign=bottom;endArrow=open;endFill=0;dashed=1;rounded=0;fontSize=11;strokeColor=#CC6600;\" edge=\"1\" parent=\"1\">&#xa;          <mxGeometry relative=\"1\" as=\"geometry\">&#xa;            <mxPoint x=\"1450\" y=\"975\" as=\"sourcePoint\"/>&#xa;            <mxPoint x=\"1260\" y=\"975\" as=\"targetPoint\"/>&#xa;          </mxGeometry>&#xa;        </mxCell>&#xa;&#xa;        <!-- Retry self-call -->&#xa;        <mxCell id=\"m15\" value=\"retry with exponential&#10;backoff (configurable)\" style=\"html=1;verticalAlign=bottom;endArrow=block;endFill=1;rounded=0;fontSize=10;strokeColor=#CC6600;curved=1;\" edge=\"1\" parent=\"1\">&#xa;          <mxGeometry relative=\"1\" as=\"geometry\">&#xa;            <mxPoint x=\"1265\" y=\"1000\" as=\"sourcePoint\"/>&#xa;            <mxPoint x=\"1265\" y=\"1030\" as=\"targetPoint\"/>&#xa;            <Array as=\"points\">&#xa;              <mxPoint x=\"1330\" y=\"1000\"/>&#xa;              <mxPoint x=\"1330\" y=\"1030\"/>&#xa;            </Array>&#xa;          </mxGeometry>&#xa;        </mxCell>&#xa;&#xa;        <mxCell id=\"m16\" value=\"[retries exhausted] move payload\" style=\"html=1;verticalAlign=bottom;endArrow=block;endFill=1;rounded=0;fontSize=10;strokeColor=#CC0000;dashed=1;\" edge=\"1\" parent=\"1\">&#xa;          <mxGeometry relative=\"1\" as=\"geometry\">&#xa;            <mxPoint x=\"1260\" y=\"1060\" as=\"sourcePoint\"/>&#xa;            <mxPoin